window.OWN_BUNDLES=window.OWN_BUNDLES||{};window.OWN_BUNDLES["zapier"]={html:"<div class=\"own-zapier\">\n  <header class=\"za-nav\">\n    <a class=\"za-brand\" href=\"#za-top\">\n      <span class=\"za-mark\" aria-hidden=\"true\">\n        <svg viewBox=\"0 0 32 32\"><path d=\"M13 4h6v7l5-4 3 5-6 4 6 4-3 5-5-4v7h-6v-7l-5 4-3-5 6-4-6-4 3-5 5 4z\" fill=\"#ff4f00\"/></svg>\n      </span>\n      <span class=\"za-brand-name\">Northwind</span>\n    </a>\n    <nav class=\"za-nav-links\" aria-label=\"Primary\">\n      <a href=\"#za-workflow\">Product</a>\n      <a href=\"#za-regions\">Regions</a>\n      <a href=\"#za-pricing\">Pricing</a>\n    </nav>\n    <div class=\"za-nav-actions\">\n      <a class=\"za-link\" href=\"#\">Log in</a>\n      <a class=\"za-btn za-btn-primary za-btn-sm\" href=\"#za-cta\">Sign up</a>\n    </div>\n  </header>\n\n  <main>\n    <section class=\"za-hero\" id=\"za-top\" aria-labelledby=\"zaHeroH\">\n      <div class=\"za-hero-copy\">\n        <p class=\"za-eyebrow\">Operations analytics</p>\n        <h1 class=\"za-hero-title\" id=\"zaHeroH\">Connect the floor. Watch it run.</h1>\n        <p class=\"za-hero-lead\">Northwind wires every region, pipeline and shift into one live board — so operations teams stop rebuilding reports and start running the operation.</p>\n        <div class=\"za-hero-cta\">\n          <a class=\"za-btn za-btn-primary\" href=\"#za-cta\">Start free</a>\n          <a class=\"za-btn za-btn-tertiary\" href=\"#za-workflow\">See how it works</a>\n        </div>\n        <p class=\"za-hero-note\">Free while you build · No card required</p>\n      </div>\n      <div class=\"za-workflow\" id=\"za-workflow\" aria-label=\"Workflow builder mock\">\n        <div class=\"za-flow-node\">\n          <span class=\"za-node-ico za-node-trigger\" aria-hidden=\"true\">\n            <svg viewBox=\"0 0 24 24\"><path d=\"M13 2 4 14h6l-1 8 9-12h-6z\"/></svg>\n          </span>\n          <span class=\"za-node-body\"><b>Trigger</b><span>New shift starts</span></span>\n        </div>\n        <span class=\"za-flow-line\" aria-hidden=\"true\"></span>\n        <div class=\"za-flow-node\">\n          <span class=\"za-node-ico za-node-action\" aria-hidden=\"true\">\n            <svg viewBox=\"0 0 24 24\"><path d=\"M4 18V8m5 10V4m5 14v-7m5 7V6\"/></svg>\n          </span>\n          <span class=\"za-node-body\"><b>Action</b><span>Refresh region board</span></span>\n        </div>\n        <span class=\"za-flow-line\" aria-hidden=\"true\"></span>\n        <div class=\"za-flow-node\">\n          <span class=\"za-node-ico za-node-alert\" aria-hidden=\"true\">\n            <svg viewBox=\"0 0 24 24\"><path d=\"M18 8a6 6 0 1 0-12 0c0 7-3 9-3 9h18s-3-2-3-9M13.7 21a2 2 0 0 1-3.4 0\"/></svg>\n          </span>\n          <span class=\"za-node-body\"><b>Alert</b><span>Page the supervisor</span></span>\n        </div>\n      </div>\n    </section>\n\n    <section class=\"za-logos\" aria-label=\"Trusted by operations teams\">\n      <p class=\"za-logos-label\">Running the floor at teams like</p>\n      <ul class=\"za-logos-row\">\n        <li>Meridian Logistics</li>\n        <li>Northgate Foods</li>\n        <li>Bluepeak Energy</li>\n        <li>Harbor Freight Co.</li>\n        <li>Cedarline Health</li>\n      </ul>\n    </section>\n\n    <section class=\"za-features\" id=\"za-features\" aria-labelledby=\"zaFeatH\">\n      <div class=\"za-sec-head\">\n        <p class=\"za-eyebrow\">Why Northwind</p>\n        <h2 class=\"za-sec-title\" id=\"zaFeatH\">Automate the operation, not just the report</h2>\n      </div>\n      <div class=\"za-feat-grid\">\n        <article class=\"za-card za-card-cream\">\n          <span class=\"za-ico\" aria-hidden=\"true\">\n            <svg viewBox=\"0 0 24 24\"><path d=\"M4 18V8m5 10V4m5 14v-7m5 7V6\"/></svg>\n          </span>\n          <h3>Live throughput</h3>\n          <p>One governed metric across every region — no re-keyed totals, no overnight surprises.</p>\n        </article>\n        <article class=\"za-card za-card-cream\">\n          <span class=\"za-ico\" aria-hidden=\"true\">\n            <svg viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"8\"/><path d=\"M12 4v8l6 3\"/></svg>\n          </span>\n          <h3>Shift-aware alerts</h3>\n          <p>Thresholds respect the roster, so the right supervisor is paged at the right hour.</p>\n        </article>\n        <article class=\"za-card za-card-dark\">\n          <span class=\"za-ico za-ico-dark\" aria-hidden=\"true\">\n            <svg viewBox=\"0 0 24 24\"><path d=\"M4 7h16M4 12h10M4 17h13\"/></svg>\n          </span>\n          <h3>Regional roll-ups</h3>\n          <p>Five regions, one true total. Every roll-up traces back to its source stream.</p>\n        </article>\n      </div>\n    </section>\n\n    <section class=\"za-regions\" id=\"za-regions\" aria-labelledby=\"zaRegH\">\n      <div class=\"za-sec-head\">\n        <p class=\"za-eyebrow\">By region</p>\n        <h2 class=\"za-sec-title\" id=\"zaRegH\">Where the volume sits today</h2>\n      </div>\n      <div class=\"za-region-grid\">\n        <div class=\"za-region\">\n          <span class=\"za-region-label\">Northwest</span>\n          <span class=\"za-region-num\" data-za-count=\"18420\">18,420</span>\n          <span class=\"za-bar\"><span class=\"za-bar-fill\" style=\"--w:100%\"></span></span>\n        </div>\n        <div class=\"za-region\">\n          <span class=\"za-region-label\">Eastern Seaboard</span>\n          <span class=\"za-region-num\" data-za-count=\"15870\">15,870</span>\n          <span class=\"za-bar\"><span class=\"za-bar-fill\" style=\"--w:86%\"></span></span>\n        </div>\n        <div class=\"za-region\">\n          <span class=\"za-region-label\">Pacific</span>\n          <span class=\"za-region-num\" data-za-count=\"14030\">14,030</span>\n          <span class=\"za-bar\"><span class=\"za-bar-fill\" style=\"--w:76%\"></span></span>\n        </div>\n        <div class=\"za-region\">\n          <span class=\"za-region-label\">Gulf Coast</span>\n          <span class=\"za-region-num\" data-za-count=\"12240\">12,240</span>\n          <span class=\"za-bar\"><span class=\"za-bar-fill\" style=\"--w:66%\"></span></span>\n        </div>\n        <div class=\"za-region\">\n          <span class=\"za-region-label\">Prairie</span>\n          <span class=\"za-region-num\" data-za-count=\"9610\">9,610</span>\n          <span class=\"za-bar\"><span class=\"za-bar-fill\" style=\"--w:52%\"></span></span>\n        </div>\n      </div>\n    </section>\n\n    <section class=\"za-pricing\" id=\"za-pricing\" aria-labelledby=\"zaPriceH\">\n      <div class=\"za-sec-head\">\n        <p class=\"za-eyebrow\">Pricing</p>\n        <h2 class=\"za-sec-title\" id=\"zaPriceH\">Plans that scale with the floor</h2>\n      </div>\n      <div class=\"za-price-grid\">\n        <article class=\"za-price-card\">\n          <h3>Starter</h3>\n          <p class=\"za-price\"><span>$0</span> / month</p>\n          <p class=\"za-price-lead\">One board, one region.</p>\n          <ul class=\"za-feats\"><li>1 live board</li><li>3 streams</li><li>7-day history</li></ul>\n          <a class=\"za-btn za-btn-tertiary za-btn-block\" href=\"#\">Get started</a>\n        </article>\n        <article class=\"za-price-card za-price-feat\">\n          <span class=\"za-chip\">Most popular</span>\n          <h3>Growth</h3>\n          <p class=\"za-price\"><span>$240</span> / month</p>\n          <p class=\"za-price-lead\">For multi-region teams.</p>\n          <ul class=\"za-feats\"><li>Unlimited boards</li><li>40 streams</li><li>Shift-aware alerts</li><li>Versioned history</li></ul>\n          <a class=\"za-btn za-btn-primary za-btn-block\" href=\"#\">Start free trial</a>\n        </article>\n        <article class=\"za-price-card\">\n          <h3>Scale</h3>\n          <p class=\"za-price\"><span>Contact us</span></p>\n          <p class=\"za-price-lead\">For global networks.</p>\n          <ul class=\"za-feats\"><li>Everything in Growth</li><li>SSO and audit log</li><li>Dedicated modeler</li></ul>\n          <a class=\"za-btn za-btn-tertiary za-btn-block\" href=\"#\">Talk to sales</a>\n        </article>\n      </div>\n    </section>\n\n    <section class=\"za-cta\" id=\"za-cta\" aria-labelledby=\"zaCtaH\">\n      <div class=\"za-cta-inner\">\n        <h2 class=\"za-cta-title\" id=\"zaCtaH\">Automate your operation today</h2>\n        <p class=\"za-cta-lead\">Free while you build. Add your first region in minutes.</p>\n        <div class=\"za-hero-cta\">\n          <a class=\"za-btn za-btn-primary\" href=\"#\">Start free</a>\n          <a class=\"za-btn za-btn-outline-inv\" href=\"#\">Book a demo</a>\n        </div>\n      </div>\n    </section>\n  </main>\n\n  <footer class=\"za-footer\">\n    <div class=\"za-foot-grid\">\n      <div class=\"za-foot-brand\">\n        <span class=\"za-brand-name za-brand-foot\">Northwind</span>\n        <p>Operations analytics for the people running the floor.</p>\n      </div>\n      <nav class=\"za-foot-col\" aria-label=\"Product\">\n        <h4>Product</h4>\n        <a href=\"#za-features\">Platform</a>\n        <a href=\"#za-regions\">Regions</a>\n        <a href=\"#za-pricing\">Pricing</a>\n      </nav>\n      <nav class=\"za-foot-col\" aria-label=\"Company\">\n        <h4>Company</h4>\n        <a href=\"#\">About</a>\n        <a href=\"#\">Careers</a>\n        <a href=\"#\">Contact</a>\n      </nav>\n      <nav class=\"za-foot-col\" aria-label=\"Resources\">\n        <h4>Resources</h4>\n        <a href=\"#\">Docs</a>\n        <a href=\"#\">Changelog</a>\n        <a href=\"#\">Status</a>\n      </nav>\n    </div>\n    <div class=\"za-foot-base\">\n      <span>Sample data — showcase only</span>\n      <span>&copy; 2026 Northwind</span>\n    </div>\n  </footer>\n</div>\n",css:"/* ══ ZAPIER — own layout for showcase.html ═════════════════════════════════\n   Ported from the Zapier design language in DESIGN.md: warm-cream canvas\n   #fffefb (never pure white), deep coffee ink #201515 (never pure black),\n   single saturated orange CTA #ff4f00, Degular Display weight 500 hero (Inter\n   500 substitute) paired with Inter, 12px radius on buttons + cards, cream\n   #f8f4f0 soft surfaces as the primary elevation cue. Scoped `.own-zapier`. */\n\n.own-zapier {\n  --za-orange: #ff4f00;\n  --za-on-primary: #fffefb;\n  --za-ink: #201515;\n  --za-ink-soft: #2f2a26;\n  --za-body: #605d52;\n  --za-body-mid: #939084;\n  --za-mute: #c5c0b1;\n  --za-canvas: #fffefb;\n  --za-canvas-soft: #f8f4f0;\n  --za-display: 'Degular Display', 'Inter', system-ui, -apple-system, sans-serif;\n  --za-gut: clamp(20px, 4cqi, 48px);\n\n  position: relative;\n  background: var(--za-canvas);\n  color: var(--za-ink);\n  font-family: var(--za-display);\n  font-size: 18px;\n  line-height: 1.5;\n  -webkit-font-smoothing: antialiased;\n  text-align: left;\n  border-radius: 13px;\n}\n\n.own-zapier *, .own-zapier *::before, .own-zapier *::after { box-sizing: border-box; }\n.own-zapier p { margin: 0; }\n.own-zapier a { color: inherit; text-decoration: none; }\n.own-zapier :focus-visible { outline: 3px solid var(--za-orange); outline-offset: 2px; border-radius: 6px; }\n.own-zapier .za-eyebrow {\n  font-size: 14px; font-weight: 500; letter-spacing: 1px; text-transform: uppercase;\n  color: var(--za-ink); margin-bottom: 14px;\n}\n.own-zapier .za-sec-title {\n  font-size: clamp(28px, 4.4cqi, 48px); font-weight: 500; line-height: 1; letter-spacing: -.02em;\n  max-width: 22ch;\n}\n.own-zapier .za-sec-head { max-width: 1280px; margin: 0 auto 40px; }\n\n/* ── buttons ─────────────────────────────────────────────────────────────── */\n.own-zapier .za-btn {\n  display: inline-flex; align-items: center; justify-content: center; gap: 8px;\n  font-family: var(--za-display); font-size: 18px; font-weight: 600;\n  padding: 12px 24px; border-radius: 12px; border: 1px solid transparent;\n  cursor: pointer; transition: background-color .18s ease, border-color .18s ease, transform .18s ease;\n}\n.own-zapier .za-btn:active { transform: translateY(1px); }\n.own-zapier .za-btn-sm { padding: 8px 16px; font-size: 14px; }\n.own-zapier .za-btn-primary { background: var(--za-orange); color: var(--za-on-primary); }\n.own-zapier .za-btn-primary:hover { background: #e64700; }\n.own-zapier .za-btn-tertiary { background: var(--za-canvas); color: var(--za-ink); border-color: var(--za-ink); }\n.own-zapier .za-btn-tertiary:hover { background: var(--za-canvas-soft); }\n.own-zapier .za-btn-block { width: 100%; margin-top: auto; }\n.own-zapier .za-btn-outline-inv { background: transparent; color: var(--za-canvas); border-color: rgba(255,254,251,.4); }\n.own-zapier .za-btn-outline-inv:hover { border-color: var(--za-canvas); }\n.own-zapier .za-link { font-size: 16px; font-weight: 600; }\n\n/* ── nav ─────────────────────────────────────────────────────────────────── */\n.own-zapier .za-nav {\n  position: sticky; top: 68px; z-index: 30;\n  display: flex; align-items: center; gap: 32px; height: 64px; padding: 0 var(--za-gut);\n  background: rgba(255,254,251,.9); backdrop-filter: blur(12px);\n  border-bottom: 1px solid rgba(32,21,21,.1);\n}\n.own-zapier .za-brand { display: inline-flex; align-items: center; gap: 9px; }\n.own-zapier .za-mark { display: grid; place-items: center; width: 28px; height: 28px; border-radius: 8px; background: #fff2ec; }\n.own-zapier .za-mark svg { width: 20px; height: 20px; }\n.own-zapier .za-brand-name { font-size: 20px; font-weight: 600; letter-spacing: -.02em; }\n.own-zapier .za-nav-links { display: flex; align-items: center; gap: 24px; }\n.own-zapier .za-nav-links a { font-size: 16px; font-weight: 500; color: var(--za-body); }\n.own-zapier .za-nav-links a:hover { color: var(--za-ink); }\n.own-zapier .za-nav-actions { margin-left: auto; display: flex; align-items: center; gap: 18px; }\n\n/* ── hero ────────────────────────────────────────────────────────────────── */\n.own-zapier .za-hero {\n  display: grid; grid-template-columns: 1fr 1fr; gap: 56px; align-items: center;\n  max-width: 1280px; margin: 0 auto; padding: 80px var(--za-gut) 64px;\n}\n.own-zapier .za-hero-title {\n  font-size: clamp(40px, 6.6cqi, 56px); font-weight: 500; line-height: 1; letter-spacing: -.03em;\n  max-width: 14ch;\n}\n.own-zapier .za-hero-lead { font-size: 20px; line-height: 1.5; letter-spacing: -.2px; color: var(--za-body); max-width: 46ch; margin-top: 22px; }\n.own-zapier .za-hero-cta { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 30px; }\n.own-zapier .za-hero-note { font-size: 14px; color: var(--za-body-mid); margin-top: 16px; }\n\n/* ── workflow builder (illustrative) ─────────────────────────────────────── */\n.own-zapier .za-workflow {\n  display: flex; flex-direction: column; gap: 0; padding: 28px;\n  background: var(--za-canvas-soft); border: 1px solid rgba(32,21,21,.1); border-radius: 12px;\n}\n.own-zapier .za-flow-node {\n  display: flex; align-items: center; gap: 14px; padding: 16px;\n  background: var(--za-canvas); border: 1px solid rgba(32,21,21,.12); border-radius: 12px;\n}\n.own-zapier .za-node-ico { display: grid; place-items: center; width: 40px; height: 40px; border-radius: 12px; flex: none; }\n.own-zapier .za-node-ico svg { width: 20px; height: 20px; fill: none; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }\n.own-zapier .za-node-trigger { background: #fff2ec; }\n.own-zapier .za-node-trigger svg { stroke: var(--za-orange); }\n.own-zapier .za-node-action { background: var(--za-canvas-soft); }\n.own-zapier .za-node-action svg { stroke: var(--za-ink); }\n.own-zapier .za-node-alert { background: #eaf5ea; }\n.own-zapier .za-node-alert svg { stroke: #2f7d32; }\n.own-zapier .za-node-body { display: flex; flex-direction: column; gap: 2px; }\n.own-zapier .za-node-body b { font-size: 16px; font-weight: 600; }\n.own-zapier .za-node-body span { font-size: 14px; color: var(--za-body); }\n.own-zapier .za-flow-line { width: 2px; height: 22px; margin-left: 36px; background: var(--za-mute); }\n\n/* ── logos ───────────────────────────────────────────────────────────────── */\n.own-zapier .za-logos { padding: 16px var(--za-gut) 8px; max-width: 1280px; margin: 0 auto; text-align: center; }\n.own-zapier .za-logos-label { font-size: 14px; color: var(--za-body-mid); margin-bottom: 18px; }\n.own-zapier .za-logos-row {\n  list-style: none; display: flex; flex-wrap: wrap; justify-content: center; gap: 18px 40px;\n  margin: 0; padding: 0;\n}\n.own-zapier .za-logos-row li { font-size: 20px; font-weight: 500; letter-spacing: -.02em; color: var(--za-body); }\n\n/* ── features ────────────────────────────────────────────────────────────── */\n.own-zapier .za-features { padding: 72px var(--za-gut) 24px; max-width: 1280px; margin: 0 auto; }\n.own-zapier .za-feat-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; }\n.own-zapier .za-card {\n  display: flex; flex-direction: column; gap: 14px; padding: 24px;\n  border-radius: 12px; min-height: 220px;\n}\n.own-zapier .za-card-cream { background: var(--za-canvas-soft); }\n.own-zapier .za-card-dark { background: var(--za-ink); color: var(--za-on-primary); }\n.own-zapier .za-ico { display: inline-grid; place-items: center; width: 44px; height: 44px; border-radius: 12px; background: var(--za-canvas); }\n.own-zapier .za-ico svg { width: 22px; height: 22px; fill: none; stroke: var(--za-orange); stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }\n.own-zapier .za-ico-dark { background: rgba(255,79,0,.16); }\n.own-zapier .za-ico-dark svg { stroke: #ff8a55; }\n.own-zapier .za-card h3 { font-size: 24px; font-weight: 600; letter-spacing: -.02em; }\n.own-zapier .za-card p { font-size: 18px; line-height: 1.5; }\n.own-zapier .za-card-cream p { color: var(--za-body); }\n.own-zapier .za-card-dark p { color: #d8d2c8; }\n\n/* ── regions ─────────────────────────────────────────────────────────────── */\n.own-zapier .za-regions { padding: 72px var(--za-gut); background: var(--za-canvas-soft); margin-top: 48px; }\n.own-zapier .za-region-grid { display: flex; flex-direction: column; gap: 4px; max-width: 1280px; margin: 0 auto; }\n.own-zapier .za-region {\n  display: grid; grid-template-columns: 1.2fr 120px 1fr; align-items: center; gap: 20px;\n  padding: 16px 20px; background: var(--za-canvas); border: 1px solid rgba(32,21,21,.1); border-radius: 12px;\n}\n.own-zapier .za-region-label { font-size: 18px; font-weight: 600; }\n.own-zapier .za-region-num { font-size: 20px; font-weight: 600; font-variant-numeric: tabular-nums; text-align: right; }\n.own-zapier .za-bar { display: block; height: 10px; border-radius: 9999px; background: #eae4db; overflow: hidden; }\n.own-zapier .za-bar-fill { display: block; height: 100%; width: var(--w, 50%); border-radius: 9999px; background: var(--za-orange); }\n\n/* ── pricing ─────────────────────────────────────────────────────────────── */\n.own-zapier .za-pricing { padding: 72px var(--za-gut) 24px; max-width: 1280px; margin: 0 auto; }\n.own-zapier .za-price-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; align-items: stretch; }\n.own-zapier .za-price-card {\n  position: relative; display: flex; flex-direction: column; gap: 14px; padding: 24px;\n  border-radius: 12px; background: var(--za-canvas); border: 1px solid var(--za-ink);\n}\n.own-zapier .za-price-feat { background: var(--za-ink); color: var(--za-on-primary); border-color: var(--za-ink); }\n.own-zapier .za-chip {\n  position: absolute; top: 20px; right: 20px; padding: 3px 12px; border-radius: 9999px;\n  font-size: 14px; font-weight: 600; background: var(--za-orange); color: var(--za-on-primary);\n}\n.own-zapier .za-price-card h3 { font-size: 24px; font-weight: 600; letter-spacing: -.02em; }\n.own-zapier .za-price { font-size: 15px; color: var(--za-body-mid); }\n.own-zapier .za-price span { font-size: 40px; font-weight: 500; letter-spacing: -.03em; color: var(--za-ink); }\n.own-zapier .za-price-feat .za-price { color: #c9c0b5; }\n.own-zapier .za-price-feat .za-price span { color: var(--za-canvas); }\n.own-zapier .za-price-lead { font-size: 16px; color: var(--za-body); }\n.own-zapier .za-price-feat .za-price-lead { color: #c9c0b5; }\n.own-zapier .za-feats { list-style: none; margin: 4px 0 8px; padding: 0; display: flex; flex-direction: column; gap: 10px; }\n.own-zapier .za-feats li { position: relative; padding-left: 26px; font-size: 18px; color: var(--za-body); }\n.own-zapier .za-price-feat .za-feats li { color: #e2dbd1; }\n.own-zapier .za-feats li::before {\n  content: ''; position: absolute; left: 2px; top: 8px; width: 12px; height: 7px;\n  border-left: 2px solid var(--za-orange); border-bottom: 2px solid var(--za-orange);\n  transform: rotate(-45deg);\n}\n\n/* ── CTA ─────────────────────────────────────────────────────────────────── */\n.own-zapier .za-cta { padding: 24px var(--za-gut) 64px; }\n.own-zapier .za-cta-inner {\n  max-width: 1280px; margin: 0 auto; text-align: center; padding: 72px 40px;\n  border-radius: 12px; background: var(--za-ink); color: var(--za-on-primary);\n}\n.own-zapier .za-cta-title { font-size: clamp(32px, 4.6cqi, 56px); font-weight: 500; letter-spacing: -.03em; line-height: 1; }\n.own-zapier .za-cta-lead { font-size: 20px; color: #c9c0b5; margin-top: 16px; }\n.own-zapier .za-cta .za-hero-cta { justify-content: center; }\n\n/* ── footer ──────────────────────────────────────────────────────────────── */\n.own-zapier .za-footer { background: var(--za-ink); color: var(--za-canvas-soft); padding: 64px var(--za-gut) 32px; }\n.own-zapier .za-foot-grid { display: grid; grid-template-columns: 1.6fr repeat(3, 1fr); gap: 32px; max-width: 1280px; margin: 0 auto; }\n.own-zapier .za-brand-foot { color: var(--za-canvas); }\n.own-zapier .za-foot-brand p { font-size: 16px; line-height: 1.6; color: #b3aca2; margin-top: 12px; max-width: 32ch; }\n.own-zapier .za-foot-col { display: flex; flex-direction: column; gap: 10px; }\n.own-zapier .za-foot-col h4 { font-size: 14px; font-weight: 600; color: var(--za-orange); margin-bottom: 4px; }\n.own-zapier .za-foot-col a { font-size: 16px; color: #b3aca2; }\n.own-zapier .za-foot-col a:hover { color: var(--za-canvas); }\n.own-zapier .za-foot-base {\n  display: flex; justify-content: space-between; gap: 16px; flex-wrap: wrap;\n  max-width: 1280px; margin: 48px auto 0; padding-top: 20px;\n  border-top: 1px solid rgba(255,254,251,.14); font-size: 14px; color: #8f887e;\n}\n\n/* ── responsive — @container frame ───────────────────────────────────────── */\n@container frame (max-width: 1100px) {\n  .own-zapier .za-hero { grid-template-columns: 1fr; gap: 40px; padding-top: 56px; }\n  .own-zapier .za-feat-grid { grid-template-columns: repeat(2, 1fr); }\n  .own-zapier .za-price-grid { grid-template-columns: repeat(2, 1fr); }\n  .own-zapier .za-price-feat { grid-column: span 2; }\n  .own-zapier .za-foot-grid { grid-template-columns: 1fr 1fr; }\n  .own-zapier .za-foot-brand { grid-column: span 2; }\n}\n@container frame (max-width: 760px) {\n  .own-zapier .za-nav-links { display: none; }\n  .own-zapier .za-feat-grid { grid-template-columns: 1fr; }\n  .own-zapier .za-price-grid { grid-template-columns: 1fr; }\n  .own-zapier .za-price-feat { grid-column: span 1; }\n  .own-zapier .za-region { grid-template-columns: 1.4fr 1fr; }\n  .own-zapier .za-region .za-bar { display: none; }\n  .own-zapier .za-cta-inner { padding: 48px 24px; }\n}\n@container frame (max-width: 430px) {\n  .own-zapier .za-hero-cta { flex-direction: column; }\n  .own-zapier .za-hero-cta .za-btn { width: 100%; }\n  .own-zapier .za-logos-row li { font-size: 17px; }\n  .own-zapier .za-region { grid-template-columns: 1fr; gap: 6px; }\n  .own-zapier .za-region-num { text-align: left; }\n  .own-zapier .za-foot-grid { grid-template-columns: 1fr; }\n  .own-zapier .za-foot-brand { grid-column: span 1; }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .own-zapier .za-btn { transition: none; }\n}\n"};
/* ══ ZAPIER — own layout behaviour for showcase.html ═══════════════════════
   Registers window.OWN_LAYOUTS['zapier'].init(root). Counts the regional
   figures up on first reveal. init returns a cleanup that cancels rAF and
   disconnects observers. Query only inside `root`. */

(function () {
  var OWN = (window.OWN_LAYOUTS = window.OWN_LAYOUTS || {});

  OWN['zapier'] = {
    init: function (root) {
      var reduced = false;
      try { reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch (e) { /* ignore */ }

      var rafs = [];
      var observers = [];

      function raf(fn) { var id = requestAnimationFrame(fn); rafs.push(id); return id; }
      function fmt(n) { return Math.round(n).toLocaleString('en-US'); }

      function countTo(el) {
        var target = Number(el.getAttribute('data-za-count'));
        if (!isFinite(target)) return;
        var start = 0;
        function step(ts) {
          if (!start) start = ts;
          var p = Math.min(1, (ts - start) / 900);
          var eased = 1 - Math.pow(1 - p, 3);
          el.textContent = fmt(target * eased);
          if (p < 1) raf(step);
        }
        raf(step);
      }

      var nums = root.querySelectorAll('[data-za-count]');
      if (reduced || typeof IntersectionObserver === 'undefined') {
        nums.forEach(function (el) { var t = Number(el.getAttribute('data-za-count')); if (isFinite(t)) el.textContent = fmt(t); });
      } else {
        var io = new IntersectionObserver(function (entries) {
          entries.forEach(function (en) { if (en.isIntersecting) { countTo(en.target); io.unobserve(en.target); } });
        }, { threshold: .4 });
        nums.forEach(function (el) { io.observe(el); });
        observers.push(io);
      }

      return function cleanup() {
        rafs.forEach(function (id) { cancelAnimationFrame(id); });
        observers.forEach(function (o) { try { o.disconnect(); } catch (e) { /* ignore */ } });
      };
    }
  };
})();
